phase1.code:
// ---- Closures capture their environment ----

fn main() {
    // ---- Immutable capture ----
    let name = String::from("Hero");
    let print_name = || {
        println!("Name: {}", name);
    };
    print_name();
    println!("Still have name: {}", name);  // Works!

    // ---- Mutable capture ----
    let mut health = 100;
    let mut take_damage = || {
        health -= 10;
        health
    };
    println!("Health: {}", take_damage());
    println!("Health: {}", take_damage());

    // ---- Ownership capture (move) ----
    let player = String::from("Aragorn");
    let consume = move || {
        println!("Player: {}", player);
        // player is moved into the closure
    };
    consume();
    // println!("{}", player);  // ERROR! player moved

    // ---- Capture by reference ----
    let mut score = 0;
    {
        let mut add_score = || {
            score += 10;
        };
        add_score();
        add_score();
        // add_score goes out of scope here
    }
    println!("Score: {}", score);  // Works because closure is dropped

    // ---- Multiple closures capturing the same variable ----
    let mut gold = 50;
    {
        let add_gold = || {
            gold += 10;
        };
        add_gold();
        // gold is mutably borrowed here
    }

    let read_gold = || {
        println!("Gold: {}", gold);
    };
    read_gold();

    // ---- Closure with multiple captures ----
    let mut player_name = String::from("Hero");
    let mut player_health = 100;

    let mut update_player = || {
        player_name.push_str(" the Brave");
        player_health += 20;
    };
    update_player();
    println!("Name: {}, Health: {}", player_name, player_health);

    // ---- Move closure with multiple captures ----
    let item1 = String::from("Sword");
    let item2 = String::from("Shield");

    let consume_items = move || {
        println!("Items: {} and {}", item1, item2);
    };
    consume_items();
    // item1 and item2 are moved into the closure

    // ---- Closure that returns a closure ----
    let make_adder = || {
        let x = 10;
        move |y| x + y
    };

    let adder = make_adder();
    println!("add_10(5) = {}", adder(5));
}

phase2.brokenCode:
fn main() {
    let name = String::from("Hero");
    let print_name = move || {
        println!("Name: {}", name);
    };
    println!("{}", name);  // ERROR! name was moved
}

phase2.errorMessage:
error[E0382]: borrow of moved value: `name`
 --> src/main.rs:6:20
  |
2 |     let name = String::from("Hero");
  |         ---- move occurs because `name` has type `String`, which does not implement the `Copy` trait
3 |     let print_name = move || {
  |                      ------- value moved into closure here
4 |         println!("Name: {}", name);
  |                             ---- variable moved due to use in closure
5 |     };
6 |     println!("{}", name);  // ERROR! name was moved
  |                    ^^^^ value borrowed here after move

For more information about this error, try `rustc --explain E0382`.

phase2.explanation:
Using `move` takes ownership of `name`, so you can't use it after.

**The fix:**
```rust
let print_name = || {  // Remove move
    println!("Name: {}", name);
};
println!("{}", name);  // Works!
```

**Rust-chan says:**
"`move` takes ownership. Only use it when you need to."
